<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\User; use Pterodactyl\Models\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class ImportHost extends Model { public const RESOURCE_NAME = 'import_host'; public const MODES = ['sftp', 'ftp']; public const MAX_PER_USER = 25; protected $table = 'dezerx_import_hosts'; protected $guarded = ['id']; protected $casts = [ 'user_id' => 'int', 'port' => 'int', 'last_used_at' => 'datetime', ]; public static array $validationRules = [ 'user_id' => 'required|int|exists:users,id', 'label' => 'required|string|max:60', 'host' => 'required|string|max:255', 'port' => 'required|int|between:1,65535', 'mode' => 'required|string|in:sftp,ftp', 'path' => 'nullable|string|max:512', ]; public function toClient(): array { return [ 'id' => (string) $this->id, 'label' => (string) $this->label, 'host' => (string) $this->host, 'port' => (int) $this->port, 'mode' => (string) $this->mode, 'path' => (string) ($this->path ?? ''), 'lastUsedAt' => $this->last_used_at?->toAtomString(), ]; } public function user(): BelongsTo { return $this->belongsTo(User::class); } } 